// Meta wraps everything in entry[0].changes[0].value. Statuses and messages
// arrive on the same webhook, so classify before doing anything else.
var body = $input.first().json.body || $input.first().json;
var value = ((((body.entry || [])[0] || {}).changes || [])[0] || {}).value || {};
var msg = (value.messages || [])[0] || null;
var status = (value.statuses || [])[0] || null;

if (status) {
  return [{ json: { is_status: true, has_message: false, status_id: status.id || '',
                    status: status.status || '', recipient: status.recipient_id || '' } }];
}
if (!msg || !msg.id) {
  return [{ json: { is_status: false, has_message: false } }];
}

var text = '';
if (msg.type === 'text') { text = (msg.text || {}).body || ''; }
else if (msg.type === 'interactive') {
  var ia = msg.interactive || {};
  text = ((ia.button_reply || {}).id) || ((ia.list_reply || {}).id) ||
         ((ia.button_reply || {}).title) || ((ia.list_reply || {}).title) || '';
} else if (msg.type === 'button') { text = (msg.button || {}).text || ''; }

var profile = (((value.contacts || [])[0] || {}).profile) || {};

return [{ json: {
  is_status: false, has_message: true,
  message_id: msg.id, customer_phone: msg.from || '',
  customer_name: profile.name || '', msg_type: msg.type || 'text',
  text: text, audio_id: ((msg.audio || {}).id) || ''
} }];

var base = $('Extract Message ID').first().json;
var dedupeCode = 0;
try { dedupeCode = $('Dedupe & Save Inbound').first().json.statusCode || 0; } catch (e) { dedupeCode = 0; }
var text = base.text || '';
if (base.msg_type === 'audio') {
  try { text = $('Whisper').first().json.text || ''; } catch (e) { text = ''; }
}
text = String(text).trim();

// A voice note that produced no transcript must NOT be sent to the AI as an
// empty string - the customer would get a nonsense reply. Flag it instead.
var transcriptionFailed = (base.msg_type === 'audio' && text === '');

// Buttons carry the order they belong to, e.g. "btn_cancel:OCN-W-1042".
var ref = '';
var mm = text.match(/^(?:btn_[a-z]+|cr_[a-z]+):(OCN-[A-Z]-\d+)$/i);
if (mm) { ref = mm[1].toUpperCase(); }

return [{ json: {
  customer_phone: base.customer_phone,
  customer_name: base.customer_name,
  message_id: base.message_id,
  msg_type: base.msg_type,
  text: text,
  ref_order: ref,
  transcription_failed: transcriptionFailed,
  dedupe_status: dedupeCode
} }];

var d = $input.first().json;
var msg = 'Sorry, I could not make out that voice note.\n\n' +
  'Could you type your order instead? Or send the voice note again somewhere quieter.';
return [{ json: { customer_phone: d.customer_phone,
  outgoing: { type: 'text', text: { body: msg } } } }];

// Single decision point. Order of checks:
// staff took over > closed > privacy request > button > greeting > AI
var inp = $('Extract Input').first().json;
var ctx = $input.first().json || {};
if (Array.isArray(ctx)) { ctx = ctx[0] || {}; }

var S = ctx.settings || {};
var session = ctx.session || null;
var open = ctx.open_order || null;
var target = ctx.target_order || null;
var active = ctx.active_order || null;
var text = String(inp.text || '').trim();
var low = text.toLowerCase();

// is_open comes from the database; this is only a fallback if the RPC failed
function hoursOf(v, dflt) {
  var m = String(v || dflt).match(/^(\d{1,2}):(\d{2})/);
  return m ? Number(m[1]) + (Number(m[2]) / 60) : 0;
}
function fallbackOpen() {
  var ist = new Date(Date.now() + (5.5 * 60 * 60 * 1000));
  var hrs = ist.getUTCHours() + (ist.getUTCMinutes() / 60);
  return hrs >= hoursOf(S.open_time, '07:00') && hrs < hoursOf(S.close_time, '23:30');
}
var isOpen = (typeof ctx.is_open === 'boolean') ? ctx.is_open : fallbackOpen();
var menuUrl = S.menu_url || 'https://oceanamenunew.netlify.app';

var base = {
  customer_phone: inp.customer_phone,
  customer_name: (ctx.customer && ctx.customer.name) || inp.customer_name || '',
  text: text, msg_type: inp.msg_type, is_open: isOpen,
  open_order: open, target_order: target, active_order: active,
  settings: S, menu: ctx.menu || '',
  pincodes: ctx.pincodes || [], promos: ctx.promos || [],
  history: ctx.history || [], customer: ctx.customer || null,
  menu_url: menuUrl
};
function out(extra) { return [{ json: Object.assign({}, base, extra) }]; }

// 1. staff has taken over this chat
if (session && session.ai_enabled === false) {
  return [{ json: { route: 'staff', customer_phone: inp.customer_phone } }];
}

// 2. closed: nothing is taken, not even a Confirm tap
if (!isOpen) {
  return out({ route: 'canned', canned_reason: 'closed', canned_cta: null,
    canned_text: 'Sorry, Oceana Hotel is closed right now.\n\n' +
      'We are open ' + (S.hours || '7:00 AM to 11:30 PM, every day') + '. ' +
      'We are not taking orders until then - please message us once we open.' });
}

// 3. someone fishing for other customers' data never reaches the AI
var PRIV_WHO = /\b(other|another|all|every|previous|today'?s?|someone else'?s?)\s+(customers?|users?|clients?)\b/i;
var PRIV_WHAT = /\b(show|give|send|share|list|tell|details?|numbers?|phones?|address(es)?|orders?|data|names?|contacts?|info|information)\b/i;
var PRIV_DIRECT = /\b(customers?|users?|clients?)'?\s*(list|details|data|database|phone numbers?|numbers|contacts?)\b|\b(phone numbers?|addresses|orders)\s+of\s+(other|all|every|your)\b/i;
var privacyAsk = (PRIV_WHO.test(text) && PRIV_WHAT.test(text)) || PRIV_DIRECT.test(text);
if (privacyAsk) {
  return out({ route: 'canned', canned_reason: 'privacy', canned_cta: null,
    canned_text: 'I can only help with your own orders, so I cannot share other customers\' ' +
      'names, numbers, addresses or orders.\n\nWhat can I get you from the menu today?' });
}

// 4. buttons (and the same words typed)
var action = '';
var reason = '';
var REASONS = { cr_wrongx: 'wrong_items', cr_mind: 'changed_mind', cr_mistake: 'by_mistake',
                cr_slow: 'too_slow', cr_other: 'other' };
var m = low.match(/^(btn_confirm|btn_modify|btn_cancel|cr_wrongx|cr_wrong|cr_mind|cr_mistake|cr_slow|cr_other|cr_keep)(?::ocn-[a-z]-\d+)?$/);
if (m) {
  var k = m[1];
  if (k === 'btn_confirm') { action = 'confirm'; }
  else if (k === 'btn_modify') { action = 'modify'; }
  else if (k === 'btn_cancel') { action = 'cancel_ask'; }
  else if (k === 'cr_keep') { action = 'keep'; }
  else if (k === 'cr_wrong') { action = 'wrong'; }
  else { action = 'cancel'; reason = REASONS[k]; }
} else if (/^(confirm|confirm order|confirm my order)[\s!.]*$/.test(low)) { action = 'confirm'; }
else if (/^(modify|modify order|change order|change my order)[\s!.]*$/.test(low)) { action = 'modify'; }
else if (/^(cancel|cancel order|cancel my order|cancel it)[\s!.]*$/.test(low)) { action = 'cancel_ask'; }

if (action) {
  // A button names its order. Typed words fall back to the latest order.
  var order = inp.ref_order ? target : (open || active);
  var EDITABLE = ['draft', 'new', 'confirmed'];
  if (!order) { action = 'no_order'; }
  else if (action === 'cancel_ask' && EDITABLE.indexOf(order.status) === -1) {
    action = 'cancel';
    reason = 'after_accept';
  }
  return out({ route: 'button', button: action, cancel_reason: reason,
               order: order, order_number: order ? order.order_number : '' });
}

// 5. FAST PATH: a bare greeting, typed only. A voice note is always an order.
var GREET = /^(hi|hii+|hey+|hello+|helo|yo|good\s*(morning|afternoon|evening)|start|menu|hi there)[\s!.,?]*$/;
if (inp.msg_type !== 'audio' && GREET.test(low)) {
  return out({ route: 'greeting' });
}
return out({ route: 'ai' });

function render(phone, text, buttons, cta) {
  if (cta && cta.url) {
    return { customer_phone: phone, outgoing: { type: 'interactive', interactive: {
      type: 'cta_url', body: { text: String(text).slice(0, 1024) },
      action: { name: 'cta_url', parameters: {
        display_text: String(cta.label || 'Browse Menu').slice(0, 20), url: cta.url } } } } };
  }
  if (buttons && buttons.length > 0) {
    return { customer_phone: phone, outgoing: { type: 'interactive', interactive: {
      type: 'button', body: { text: String(text).slice(0, 1024) },
      action: { buttons: buttons.slice(0, 3).map(function (b, i) {
        return { type: 'reply', reply: { id: b.id || ('btn_' + i), title: String(b.title || b).slice(0, 20) } };
      }) } } } };
  }
  return { customer_phone: phone, outgoing: { type: 'text', text: { body: String(text) } } };
}
function rs(n){ return 'Rs ' + Number(n||0).toLocaleString('en-IN'); }

var d = $input.first().json;
var name = d.customer_name ? (' ' + d.customer_name.split(' ')[0]) : '';
var back = (d.customer && Number(d.customer.total_orders) > 0) ? ' Welcome back!' : '';
var msg = 'Hello' + name + '!' + back + ' You are chatting with Oceana Hotel, Mangalore.\n\n' +
  'Tap below to browse our full menu and order in a few taps, or just tell me what you want ' +
  '- you can type it or send a voice note.';
return [{ json: render(d.customer_phone, msg, [], { label: 'Browse Menu', url: d.menu_url + '?ph=' + d.customer_phone }) }];

