// Handles every button that does not change the database:
// modify, cancel_ask (show reasons), keep, wrong (offer a fix), no_order
var d = $input.first().json;
var o = d.order || {};
var num = o.order_number || '';
var S = d.settings || {};
var phoneTxt = S.phone || '+91 96634 28354';
var menuCta = { label: 'Browse Menu', url: d.menu_url + '?ph=' + d.customer_phone };
var editable = ['draft', 'new', 'confirmed'].indexOf(o.status) !== -1;
var res;

if (d.button === 'modify') {
  if (!editable) {
    res = render(d.customer_phone,
      'Order ' + num + ' is already being prepared, so it can no longer be changed. ' +
      'For anything urgent please call ' + phoneTxt + '.\n\n' +
      'Want to add something? Just tell me and I will set it up as a separate order.', [], null);
  } else {
    res = render(d.customer_phone,
      'Sure - tell me what to change, for example "make it 2 biryanis" or "remove the naan". ' +
      'You can type it or send a voice note.\n\n' +
      'Order ' + num + ' right now:\n' + itemLines(o) + '\nTotal: ' + rs(o.total), [], null);
  }
} else if (d.button === 'cancel_ask') {
  res = { customer_phone: d.customer_phone, outgoing: { type: 'interactive', interactive: {
    type: 'list',
    body: { text: 'Before I cancel order ' + num + ', could you tell us why? It helps us improve.' },
    action: { button: 'Choose a reason', sections: [{ title: 'Reason', rows: [
      { id: 'cr_wrong:' + num,   title: 'Wrong items',        description: 'Fix the order instead of cancelling' },
      { id: 'cr_mind:' + num,    title: 'Changed my mind' },
      { id: 'cr_mistake:' + num, title: 'Ordered by mistake' },
      { id: 'cr_slow:' + num,    title: 'Taking too long' },
      { id: 'cr_other:' + num,   title: 'Another reason' },
      { id: 'cr_keep:' + num,    title: 'Keep my order',      description: 'Do not cancel' }
    ] }] } } } };
} else if (d.button === 'wrong') {
  res = render(d.customer_phone,
    'Sorry about that! You do not have to cancel - you can fix order ' + num + ' instead.\n\n' +
    'Tap "Fix my order" and tell me what should change.',
    [{ id: 'btn_modify:' + num, title: 'Fix my order' },
     { id: 'cr_wrongx:' + num,  title: 'Cancel anyway' },
     { id: 'cr_keep:' + num,    title: 'Keep as it is' }], null);
} else if (d.button === 'keep') {
  if (o.status === 'draft') {
    res = render(d.customer_phone,
      'No problem - order ' + num + ' stays as it is. Tap Confirm when you are ready.',
      [{ id: 'btn_confirm:' + num, title: 'Confirm' },
       { id: 'btn_modify:' + num,  title: 'Modify' }], null);
  } else {
    res = render(d.customer_phone, 'Great - order ' + num + ' stays as it is.', [], null);
  }
} else {
  res = render(d.customer_phone,
    'That order is no longer open. Tell me what you would like and I will set it up for you.',
    [], menuCta);
}
return [{ json: res }];

