var r = $input.first().json || {};
var d = $('Route').first().json;
var o = r.order || d.order || {};
var num = o.order_number || d.order_number || '';
var S = d.settings || {};
var phoneTxt = S.phone || '+91 96634 28354';
var msg;
var cta = null;
if (r.result === 'cancelled') {
  msg = 'Order ' + num + ' has been cancelled. Thanks for letting us know - we hope to serve you soon.';
  cta = { label: 'Browse Menu', url: d.menu_url + '?ph=' + d.customer_phone };
} else if (r.result === 'requested') {
  msg = 'Order ' + num + ' is already being prepared, so I cannot cancel it here. ' +
        'I have alerted our team - please call ' + phoneTxt + ' and they will sort it out.';
} else if (r.result === 'already_cancelled') {
  msg = 'Order ' + num + ' was already cancelled.';
} else if (r.result === 'delivered') {
  msg = 'Order ' + num + ' has already been delivered. If something was wrong, please call ' + phoneTxt + '.';
} else {
  msg = 'Sorry, I could not cancel that just now. Please call ' + phoneTxt + ' and our team will help.';
}
return [{ json: render(d.customer_phone, msg, [], cta) }];

var d = $input.first().json;
var S = d.settings || {};
var cust = d.customer;
var hist = (d.history || []).map(function (h) {
  return (h.direction === 'inbound' ? 'Customer: ' : 'Oceana: ') +
         String(h.content || '').replace(/\s+/g, ' ').slice(0, 300);
}).join('\n');
var promos = (d.promos || []).map(function (p) { return '- ' + p.title + ' (' + p.price + ')'; }).join('\n');
var open = d.open_order;
var active = d.active_order;

function cart(o) {
  var list = (Array.isArray(o.items_json) && o.items_json.length) ? o.items_json : null;
  if (list) { return list.map(function (i) { return '  - ' + i.name + ' x' + i.quantity; }).join('\n'); }
  return String(o.items || '').split(', ').filter(Boolean)
    .map(function (s) { return '  - ' + s; }).join('\n');
}

var orderBlock = open
  ? ('OPEN ORDER ' + open.order_number + ' (' +
     (open.status === 'draft' ? 'not confirmed yet' : 'confirmed, kitchen has not started') +
     ', CAN still be changed), ' + (open.order_type || 'delivery') + ':\n' + cart(open) + '\n')
  : 'OPEN ORDER: none\n';
if (active) {
  orderBlock += 'ORDER WITH KITCHEN ' + active.order_number + ' (' +
    String(active.status || '').replace(/_/g, ' ') + ', can NOT be changed): ' + (active.items || '') + '\n';
}

var ctx = 'YOU WORK AT: ' + (S.restaurant_name || 'Oceana Hotel') + ', ' + (S.address || '') + '\n' +
 'PHONE: ' + (S.phone || '') + '   HOURS: ' + (S.hours || '') + ' (OPEN NOW)\n' +
 'CUISINES: ' + (S.cuisines || '') + '\n' +
 'PAYMENT: ' + (S.payment_methods || '') + '   MINIMUM DELIVERY ORDER: Rs ' + (S.min_order || '200') + '\n' +
 'DELIVERY: ' + (S.delivery_note || '') + ', ' + (S.delivery_time || '') + '\n' +
 'WE DELIVER TO PINCODES: ' + (d.pincodes || []).join(', ') + '\n' +
 'MENU LINK: ' + (d.menu_url || '') + '\n' +
 'IF UNSURE: ' + (S.unknown_policy || 'Say you will check with the team.') + '\n\n' +
 'CUSTOMER: ' + (cust ? ((cust.name || 'name unknown') + ', ' + (cust.total_orders || 0) + ' previous orders') : 'brand new') + '\n' +
 orderBlock +
 (hist ? ('\nRECENT CONVERSATION (oldest first):\n' + hist + '\n') : '') +
 (promos ? ('\nPROMOTIONS:\n' + promos + '\n') : '') +
 '\nMENU (name|price, ASK = market price):\n' + (d.menu || '');

return [{ json: Object.assign({}, d, { dynamicContext: ctx }) }];

var raw = '';
try { raw = $input.first().json.output || ''; } catch (e) { raw = ''; }

var ctx = $('Build Prompt').first().json;
var parsed = null;
try {
  var clean = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();
  var s = clean.indexOf('{');
  var e = clean.lastIndexOf('}');
  if (s !== -1 && e !== -1) { parsed = JSON.parse(clean.slice(s, e + 1)); }
} catch (err) { parsed = null; }

if (!parsed || !parsed.reply) {
  parsed = { intent: 'other', reply: 'Sorry, I did not catch that. Could you say it again?',
             items: [], order_type: '' };
}

var items = (Array.isArray(parsed.items) ? parsed.items : []).map(function (i) {
  return { name: String((i && i.name) || '').trim(), quantity: Number(i && i.quantity) };
}).filter(function (i) { return i.name !== ''; });

return [{ json: {
  customer_phone: ctx.customer_phone,
  customer_name: ctx.customer_name,
  intent: String(parsed.intent || 'other'),
  reply: String(parsed.reply),
  items: items,
  order_type: String(parsed.order_type || '')
} }];

// Prices and names come from the live menu digest, never from the AI.
// The AI returns the COMPLETE cart when an order is open.
var ai = $input.first().json;
var d = $('Route').first().json;
var open = d.open_order || null;
var active = d.active_order || null;

function norm(s) { return String(s || '').toLowerCase().replace(/\s+/g, ' ').trim(); }
var NAME = {};
var PRICE = {};
String(d.menu || '').split('\n').forEach(function (line) {
  var k = line.lastIndexOf('|');
  if (k < 1) { return; }
  var n = line.slice(0, k).trim();
  var p = line.slice(k + 1).trim();
  NAME[norm(n)] = n;
  PRICE[norm(n)] = (p === 'ASK') ? 0 : (Number(p) || 0);
});

var cart = [];
var unknown = [];
var pos = {};
(ai.items || []).forEach(function (i) {
  var key = norm(i.name);
  if (!key) { return; }
  if (!Object.prototype.hasOwnProperty.call(NAME, key)) { unknown.push(String(i.name)); return; }
  var q = Math.round(Number(i.quantity));
  if (!(q > 0)) { return; }
  if (Object.prototype.hasOwnProperty.call(pos, key)) {
    cart[pos[key]].quantity = Math.min(50, cart[pos[key]].quantity + q);
    return;
  }
  pos[key] = cart.length;
  cart.push({ name: NAME[key], quantity: Math.min(50, q), price: PRICE[key] });
});
function asText(list) {
  return list.map(function (i) { return i.name + ' x' + i.quantity; }).join(', ');
}
var total = cart.reduce(function (s, i) { return s + (i.price * i.quantity); }, 0);
var itemsText = asText(cart);

var decision = 'reply';
var note = '';
if (ai.intent === 'order') {
  if (unknown.length > 0) {
